exercises.schema:
CREATE TABLE posts (
  id         bigint PRIMARY KEY,
  author     text NOT NULL,
  body       text NOT NULL,
  created_at timestamptz NOT NULL
);
CREATE INDEX posts_feed_idx ON posts (created_at DESC, id DESC);
-- Exactly one row: the LAST post of the page the client already has (decoded from its cursor).
CREATE TABLE page_cursor (
  created_at timestamptz NOT NULL,
  id         bigint NOT NULL
);

CREATE TABLE articles (
  id           bigint PRIMARY KEY,
  title        text NOT NULL,
  published_at timestamptz NOT NULL
);
CREATE INDEX articles_feed_idx ON articles (published_at DESC, id DESC);

CREATE TABLE posts (
  id         bigint PRIMARY KEY,
  author     text NOT NULL,
  body       text NOT NULL,
  created_at timestamptz NOT NULL,
  hidden     boolean NOT NULL DEFAULT false
);
CREATE INDEX posts_visible_feed_idx ON posts (created_at DESC, id DESC) WHERE NOT hidden;
-- Exactly one row: the FIRST (newest) post of the page the client is looking at.
CREATE TABLE page_cursor (
  created_at timestamptz NOT NULL,
  id         bigint NOT NULL
);
